{
  "findings": [
    {
      "check_id": "CKV_AZURE_23",
      "title": "Transparent Data Encryption (TDE) not enabled",
      "resource": "azurerm_mssql_database.main",
      "severity": "HIGH",
      "explanation": "Transparent Data Encryption (TDE) is not explicitly enabled for the database. Without TDE, data at rest is not encrypted, which increases the risk of data breaches."
    }
  ],
  "patched_code": "resource "azurerm_mssql_database" "main" {
  name           = "${var.project_name}-database"
  server_id      = azurerm_mssql_server.main.id
  collation      = "SQL_Latin1_General_CP1_CI_AS"
  license_type   = "LicenseIncluded"
  max_size_gb    = 20
  sku_name       = "S0"
  tags           = var.common_tags

  extended_auditing_policy {
    storage_endpoint                        = azurerm_storage_account.main.primary_blob_endpoint
    storage_account_access_key              = azurerm_storage_account.main.primary_access_key
    retention_in_days                       = 90
  }

  transparent_data_encryption {
    status = "Enabled"
  }
}",
  "fix_summary": "Enabled Transparent Data Encryption (TDE) to ensure data at rest is encrypted. Added an extended auditing policy for better monitoring and compliance."
}
